CREATE TABLE ezsearch_object_word_link (id INT AUTO_INCREMENT NOT NULL, contentclass_attribute_id INT DEFAULT 0 NOT NULL, contentclass_id INT DEFAULT 0 NOT NULL, contentobject_id INT DEFAULT 0 NOT NULL, frequency DOUBLE PRECISION DEFAULT '0' NOT NULL, identifier VARCHAR(255) DEFAULT '' NOT NULL, integer_value INT DEFAULT 0 NOT NULL, next_word_id INT DEFAULT 0 NOT NULL, placement INT DEFAULT 0 NOT NULL, prev_word_id INT DEFAULT 0 NOT NULL, published INT DEFAULT 0 NOT NULL, section_id INT DEFAULT 0 NOT NULL, word_id INT DEFAULT 0 NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, INDEX ezsearch_object_word_link_object (contentobject_id), INDEX ezsearch_object_word_link_identifier (identifier(191)), INDEX ezsearch_object_word_link_integer_value (integer_value), INDEX ezsearch_object_word_link_word (word_id), INDEX ezsearch_object_word_link_frequency (frequency), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
